+			for _, cap := range sc.Capabilities.Add {
+				if _, bad := dangerousCapabilities[cap]; bad {
+					cerrs = errors.Join(cerrs, fmt.Errorf(
+						"%s.%s[%s].securityContext.capabilities.add[%q] is not allowed", fieldPath, group, c.Name, cap))
